# Installation

## Basic Installation

Add the Nex script to your HTML page using the latest commit hash:

```html
<script src="https://cdn.jsdelivr.net/gh/UseNex/nex-js@afd45d45f9f5025481a999dde0379b5fbde5d9ce/nex.min.js"></script>
```

## Available Games

To see all available games, use the metadata API:

```js
const aliases = window.nex.metadata.getAllAliases()
const gameInfo = window.nex.metadata.get("2048")
// { alias: "2048", name: "2048", category: "Puzzle", description: "Merge identical numbers to reach the legendary 2048 tile.", img: "https://cdn.jsdelivr.net/gh/UseNex/thumbnails@afd45d45f9f5025481a999dde0379b5fbde5d9ce/2048.webp" }
```

# Basic Usage Example

Complete example showing a game with the built-in loader.

## HTML

```html
<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.jsdelivr.net/gh/UseNex/nex-js@afd45d45f9f5025481a999dde0379b5fbde5d9ce/nex.min.js"></script>
  <style>
    body { margin: 0; background: #000; }
    nex-game {
      display: block;
      width: 100vw;
      height: 100vh;
    }
  </style>
</head>
<body>
  <!-- Uses built-in loader by default -->
  <nex-game alias="slope" gid="game-1"></nex-game>

  <script>
    const gid = "game-1"

    // Optional: track progress (built-in loader shows it automatically)
    window.nex[gid].on("progress", (data) => {
      console.log(`Loading: ${data.progress}%`)
    })

    // Auto-start when ready
    window.nex[gid].on("ready", () => {
      console.log("Game ready!")
      window.nex[gid].start()
    })

    // Handle errors
    window.nex[gid].on("error", (err) => {
      console.error("Game error:", err.message)
    })
  </script>
</body>
</html>
```

# Custom Loader Example

Create your own loading screen with custom styles and progress tracking.

## HTML

```html
<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.jsdelivr.net/gh/UseNex/nex-js@afd45d45f9f5025481a999dde0379b5fbde5d9ce/nex.min.js"></script>
  <style>
    body { margin: 0; background: #0a0a0f; }

    #loader {
      position: fixed;
      inset: 0;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      background: #0a0a0f;
      z-index: 100;
      transition: opacity 0.5s;
    }
    #loader.hidden {
      opacity: 0;
      pointer-events: none;
    }
    .spinner {
      width: 50px;
      height: 50px;
      border: 3px solid rgba(255,255,255,0.1);
      border-top-color: #6366f1;
      border-radius: 50%;
      animation: spin 0.8s linear infinite;
    }
    @keyframes spin {
      to { transform: rotate(360deg); }
    }
    #progress-text {
      margin-top: 20px;
      color: #888;
      font-family: system-ui;
      font-size: 14px;
    }

    nex-game {
      display: block;
      width: 100vw;
      height: 100vh;
    }
  </style>
</head>
<body>
  <div id="loader">
    <div class="spinner"></div>
    <div id="progress-text">0%</div>
  </div>

  <!-- Custom loader mode -->
  <nex-game alias="granny" gid="game-1" loading-screen="true"></nex-game>

  <script>
    const gid = "game-1"
    const loader = document.getElementById('loader')
    const progressText = document.getElementById('progress-text')

    // Progress events update your custom loader
    window.nex[gid].on('progress', (data) => {
      progressText.textContent = `${Math.round(data.progress)}%`
    })

    window.nex[gid].on('ready', () => {
      loader.classList.add('hidden')
      window.nex[gid].start()
    })

    window.nex[gid].on('error', (err) => {
      progressText.textContent = `Error: ${err.message}`
    })
  </script>
</body>
</html>
```

# Game Gallery Example

Create a game selection screen with thumbnails using the latest commit hash.

## HTML

```html
<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.jsdelivr.net/gh/UseNex/nex-js@afd45d45f9f5025481a999dde0379b5fbde5d9ce/nex.min.js"></script>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { 
      font-family: system-ui;
      background: #0a0a0f;
      color: #fff;
      padding: 20px;
    }
    .grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
      gap: 20px;
      max-width: 1200px;
      margin: 0 auto;
    }
    .card {
      background: #1a1a2e;
      border-radius: 12px;
      padding: 20px;
      text-align: center;
      cursor: pointer;
      transition: transform 0.2s;
    }
    .card:hover { transform: translateY(-5px); }
    .card img {
      width: 100%;
      aspect-ratio: 4/3;
      object-fit: cover;
      border-radius: 8px;
      margin-bottom: 10px;
    }
    .card h3 { font-size: 1rem; margin-bottom: 5px; }
    .card p { font-size: 0.8rem; color: #888; }
  </style>
</head>
<body>
  <div class="grid" id="gallery"></div>
  <nex-game id="game-container" style="display:none;"></nex-game>

  <script>
    const games = window.nex.metadata.getAllMetadata()
    const gallery = document.getElementById('gallery')

    Object.values(games).forEach(game => {
      const card = document.createElement('div')
      card.className = 'card'
      card.innerHTML = `
        <img src="${game.img}" alt="${game.name}" loading="lazy">
        <h3>${game.name}</h3>
        <p>${game.category}</p>
      `
      card.onclick = () => playGame(game.alias)
      gallery.appendChild(card)
    })

    function playGame(alias) {
      const container = document.getElementById('game-container')
      container.style.display = 'block'
      container.setAttribute('alias', alias)
      container.setAttribute('gid', 'gallery-game')

      window.nex['gallery-game'].on('ready', () => {
        window.nex['gallery-game'].start()
      })
    }
  </script>
</body>
</html>
```

# Dynamic Game Switching

Switch between games without reloading the page.

## HTML

```html
<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.jsdelivr.net/gh/UseNex/nex-js@afd45d45f9f5025481a999dde0379b5fbde5d9ce/nex.min.js"></script>
  <style>
    body { 
      font-family: system-ui;
      background: #0a0a0f;
      color: #fff;
      padding: 20px;
    }
    .game-container {
      width: 100%;
      height: 80vh;
      margin-top: 20px;
      border-radius: 12px;
      overflow: hidden;
    }
    .controls {
      display: flex;
      gap: 10px;
      flex-wrap: wrap;
      margin-bottom: 20px;
    }
    button {
      padding: 10px 20px;
      background: #1a1a2e;
      color: #fff;
      border: 1px solid #333;
      border-radius: 8px;
      cursor: pointer;
      transition: all 0.2s;
    }
    button:hover {
      background: #2a2a4e;
      border-color: #6366f1;
    }
  </style>
</head>
<body>
  <h1>Game Switcher</h1>
  <div class="controls">
    <button onclick="loadGame('2048')">2048</button>
    <button onclick="loadGame('slope')">Slope</button>
    <button onclick="loadGame('fnaf')">FNAF</button>
    <button onclick="loadGame('flappy-bird')">Flappy Bird</button>
    <button onclick="loadGame('cookie-clicker')">Cookie Clicker</button>
  </div>
  <div class="game-container">
    <nex-game id="game" alias="2048" gid="switcher"></nex-game>
  </div>

  <script>
    function loadGame(alias) {
      const game = document.getElementById('game')
      // Reset the game with new alias
      game.setAttribute('alias', alias)
      console.log(`Loading ${alias}...`)
    }
  </script>
</body>
</html>
```

# Performance Best Practices

## 1. Use Unique GIDs
Always use unique `gid` values for each game instance to prevent conflicts.

```html
<!-- Good -->
<nex-game alias="2048" gid="game-${Date.now()}"></nex-game>

<!-- Bad - reusing same gid -->
<nex-game alias="2048" gid="game-1"></nex-game>
```

## 2. Lazy Load Games
Only create game elements when needed.

```js
function loadGame(alias) {
  const container = document.createElement('nex-game')
  container.setAttribute('alias', alias)
  container.setAttribute('gid', `game-${Date.now()}`)
  document.body.appendChild(container)
}
```

## 3. Handle Errors Gracefully
Always listen for error events.

```js
window.nex[gid].on('error', (err) => {
  // Show user-friendly message
  document.querySelector('.error').textContent = 'Failed to load game'
})
```

## 4. Clean Up on Unmount
Remove game elements when no longer needed.

```js
function removeGame() {
  const game = document.querySelector('nex-game')
  if (game) game.remove()
}
```

## 5. Choose the Right Loader Mode

| Use Case | Recommended Mode |
|----------|------------------|
| Quick embed, no customization | Built-in loader (default) |
| Branded loading experience | Custom loader (`loading-screen="true"`) |
| Minimalist design | Custom loader |
| Rapid prototyping | Built-in loader |

## 6. Thumbnail Display
When displaying game thumbnails, use 4:3 aspect ratio for optimal display:

```css
.game-thumbnail {
  width: 100%;
  aspect-ratio: 4/3;
  object-fit: cover;
}
```

## 7. Cache for Faster Loading
After the first load, games are cached by the browser for faster subsequent loads.

```js
// Warm up the cache by preloading a game
setTimeout(() => {
  const preload = document.createElement('nex-game')
  preload.setAttribute('alias', '2048')
  preload.setAttribute('gid', 'preload')
  preload.style.display = 'none'
  document.body.appendChild(preload)
}, 1000)
```

# Custom Loader Implementation

Complete guide to implementing your own loading screen.

## Basic Custom Loader

```html
<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.jsdelivr.net/gh/UseNex/nex-js@afd45d45f9f5025481a999dde0379b5fbde5d9ce/nex.min.js"></script>
  <style>
    #loader {
      position: fixed;
      inset: 0;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      background: #0a0a0f;
      z-index: 100;
      transition: opacity 0.5s;
    }
    #loader.hidden {
      opacity: 0;
      pointer-events: none;
    }
    .spinner {
      width: 50px;
      height: 50px;
      border: 3px solid rgba(255,255,255,0.1);
      border-top-color: #6366f1;
      border-radius: 50%;
      animation: spin 0.8s linear infinite;
    }
    @keyframes spin {
      to { transform: rotate(360deg); }
    }
    #progress-text {
      margin-top: 20px;
      color: #888;
      font-family: system-ui;
      font-size: 14px;
    }
    #error-text {
      margin-top: 10px;
      color: #e11d48;
      font-family: system-ui;
      font-size: 13px;
      display: none;
    }
  </style>
</head>
<body>
  <div id="loader">
    <div class="spinner"></div>
    <div id="progress-text">0%</div>
    <div id="error-text">Failed to load game</div>
  </div>

  <nex-game alias="granny" gid="game-1" loading-screen="true"></nex-game>

  <script>
    const gid = "game-1"
    const loader = document.getElementById('loader')
    const progressText = document.getElementById('progress-text')
    const errorText = document.getElementById('error-text')

    window.nex[gid].on('progress', (data) => {
      progressText.textContent = `${Math.round(data.progress)}%`
    })

    window.nex[gid].on('ready', () => {
      loader.classList.add('hidden')
      window.nex[gid].start()
    })

    window.nex[gid].on('error', (err) => {
      errorText.style.display = 'block'
      errorText.textContent = `Error: ${err.message}`
      progressText.textContent = 'Failed'
    })
  </script>
</body>
</html>
```

## Advanced Custom Loader with Branding

```html
<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.jsdelivr.net/gh/UseNex/nex-js@afd45d45f9f5025481a999dde0379b5fbde5d9ce/nex.min.js"></script>
  <style>
    body { margin: 0; background: #0a0a0f; }

    /* Branded loader */
    #loader {
      position: fixed;
      inset: 0;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      background: linear-gradient(135deg, #0f0c29, #302b63, #24243e);
      z-index: 100;
      transition: opacity 0.6s ease;
    }
    #loader.hidden {
      opacity: 0;
      pointer-events: none;
    }

    .brand {
      font-size: 28px;
      font-weight: 900;
      color: #fff;
      text-shadow: 0 0 20px rgba(255,255,255,0.2);
      letter-spacing: 6px;
      margin-bottom: 30px;
    }
    .brand span { color: #f7d44a; }

    .progress-track {
      width: 280px;
      height: 4px;
      background: rgba(255,255,255,0.1);
      border-radius: 2px;
      overflow: hidden;
    }
    .progress-bar {
      height: 100%;
      width: 0%;
      background: linear-gradient(90deg, #f7d44a, #f7a84a);
      transition: width 0.15s ease;
    }

    .percentage {
      margin-top: 12px;
      font-size: 13px;
      color: rgba(255,255,255,0.4);
      letter-spacing: 2px;
    }

    .status {
      margin-top: 6px;
      font-size: 11px;
      color: rgba(255,255,255,0.2);
      letter-spacing: 1px;
      text-transform: uppercase;
    }
  </style>
</head>
<body>
  <div id="loader">
    <div class="brand">Nex <span>Arcade</span></div>
    <div class="progress-track">
      <div class="progress-bar" id="progress-bar"></div>
    </div>
    <div class="percentage" id="percentage">0%</div>
    <div class="status" id="status">Initializing...</div>
  </div>

  <nex-game alias="granny" gid="game-1" loading-screen="true"></nex-game>

  <script>
    const gid = "game-1"
    const loader = document.getElementById('loader')
    const progressBar = document.getElementById('progress-bar')
    const percentage = document.getElementById('percentage')
    const status = document.getElementById('status')

    const STATUSES = [
      'Initializing...',
      'Loading game...',
      'Almost ready...',
      'Ready! 🎮'
    ]

    let lastStatus = 0

    window.nex[gid].on('progress', (data) => {
      const p = Math.round(data.progress)
      progressBar.style.width = p + '%'
      percentage.textContent = p + '%'

      let idx = 0
      if (p >= 100) idx = 3
      else if (p >= 70) idx = 2
      else if (p >= 30) idx = 1
      else idx = 0

      if (idx !== lastStatus) {
        lastStatus = idx
        status.textContent = STATUSES[idx]
      }
    })

    window.nex[gid].on('ready', () => {
      loader.classList.add('hidden')
      window.nex[gid].start()
    })

    window.nex[gid].on('error', (err) => {
      status.textContent = '❌ Error'
      percentage.textContent = 'Failed'
      console.error(err)
    })
  </script>
</body>
</html>
```
